CREATE TABLE IF NOT EXISTS {schema}.mailbox_items (id {uuid} PRIMARY KEY, market_name {keyed} NOT NULL REFERENCES {schema}.markets(name), owner {uuid} NOT NULL, item_blob {blob} NOT NULL, fingerprint {keyed} NOT NULL, reason {keyed} NOT NULL, state {status} NOT NULL CHECK (state IN ('UNCLAIMED', 'CLAIMING', 'CLAIMED', 'REVIEW')), settlement_id {uuid} UNIQUE, created_at {ts} NOT NULL{defaultNow}, claimed_at {ts})
